 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let i = 0;
+  let textStart = 0;
+
+  while (i < template.length) {
+    if (template[i] === "{" && template[i + 1] === "{") {
+      if (textStart < i) {
+        tokens.push({ kind: "text", text: template.slice(textStart, i) });
+      }
+
+      let raw = false;
+      let j = i + 2;
+      if (template[j] === "{") {
+        raw = true;
+        j++;
+      }
+
+      const close = raw ? "}}}" : "}}";
+      const closeLen = raw ? 3 : 2;
+      const endIdx = template.indexOf(close, j);
+      if (endIdx === -1) {
+        throw new Error("unterminated tag");
+      }
+
+      const content = template.slice(j, endIdx).trim();
+
+      if (content.startsWith("#if ")) {
+        tokens.push({ kind: "if", path: content.slice(4).trim() });
+      } else if (content === "else") {
+        tokens.push({ kind: "else" });
+      } else if (content === "/if") {
+        tokens.push({ kind: "end" });
+      } else {
+        tokens.push({ kind: "value", expr: content, raw });
+      }
+
+      i = endIdx + closeLen;
+      textStart = i;
+    } else {
+      i++;
+    }
+  }
+
+  if (textStart < template.length) {
+    tokens.push({ kind: "text", text: template.slice(textStart) });
+  }
+
+  return tokens;
 }
